return ['domain'=>NULL,'plural-forms'=>'nplurals=2; plural=n != 1;','language'=>'sw','project-id-version'=>'Babilim 1.2.0','pot-creation-date'=>'2026-11-05T19:51:10+00:00','po-revision-date'=>'2026-11-05T19:51:10+00:00','x-generator'=>'Babilim','messages'=>['Babilim'=>'Babilim','Fills in missing translations for the plugins and themes already installed on your site.'=>'Hukamilisha tafsiri zinazokosekana za programu-jalizi na mandhari ambazo tayari zimesakinishwa kwenye tovuti yako.','That upload screen was out of date: a different upload has been prepared since. Nothing was sent. Review the current one from the Translations list.'=>'Skrini hiyo ya kupakia ilikuwa imepitwa na wakati: upakiaji mwingine umeandaliwa tangu hapo. Hakuna kilichotumwa. Kagua ule wa sasa kutoka Orodha ya tafsiri.','The free service plan gives each site a limited number of slots for plugins and themes; the slots in use are shown in Settings after you enable Babilim.'=>'Mpango wa huduma wa bure humpa kila tovuti idadi ndogo ya nafasi za programu-jalizi na mandhari; nafasi zinazotumika zinaonyeshwa katika Mipangilio baada ya kuwezesha Babilim.','Requesting a translation puts this plugin or theme on one of the free service plan\'s slots for this site (the limit is %1$d for themes and %2$d for plugins), unless it already has one. A slot stays used, and a failed translation does not free it.'=>'Kuomba tafsiri huweka programu-jalizi au mandhari hii kwenye mojawapo ya nafasi za mpango wa huduma wa bure kwa tovuti hii (kikomo ni %1$d kwa mandhari na %2$d kwa programu-jalizi), isipokuwa tayari ina nafasi. Nafasi hubaki ikitumika, na tafsiri iliyoshindwa haiiachilii.','Requesting a translation puts this plugin or theme on one of the free service plan\'s slots for this site, unless it already has one. A slot stays used, and a failed translation does not free it.'=>'Kuomba tafsiri huweka programu-jalizi au mandhari hii kwenye mojawapo ya nafasi za mpango wa huduma wa bure kwa tovuti hii, isipokuwa tayari ina nafasi. Nafasi hubaki ikitumika, na tafsiri iliyoshindwa haiiachilii.','If this plugin or theme is not on one of the free service plan\'s slots for this site yet, requesting a translation puts it on one (the limit is %1$d for themes and %2$d for plugins). A slot stays used, and a failed translation does not free it. Continue?'=>'Ikiwa programu-jalizi au mandhari hii bado haipo kwenye mojawapo ya nafasi za mpango wa huduma wa bure kwa tovuti hii, kuomba tafsiri huiweka kwenye moja (kikomo ni %1$d kwa mandhari na %2$d kwa programu-jalizi). Nafasi hubaki ikitumika, na tafsiri iliyoshindwa haiiachilii. Endelea?','If this plugin or theme is not on one of the free service plan\'s slots for this site yet, requesting a translation puts it on one. A slot stays used, and a failed translation does not free it. Continue?'=>'Ikiwa programu-jalizi au mandhari hii bado haipo kwenye mojawapo ya nafasi za mpango wa huduma wa bure kwa tovuti hii, kuomba tafsiri huiweka kwenye moja. Nafasi hubaki ikitumika, na tafsiri iliyoshindwa haiiachilii. Endelea?','%1$d site on this network is set to erase its Babilim identity when the plugin is deleted. The paid license attached to that site could then not be restored automatically; you would have to contact Babilim support at %2$s. To keep the identity, press Cancel, untick "Delete all Babilim data on uninstall" in that site\'s Babilim settings, and deactivate again. Deactivate anyway?'=>'Tovuti %1$d kwenye mtandao huu imewekwa kufuta utambulisho wake wa Babilim programu-jalizi itakapofutwa. Leseni ya kulipia iliyounganishwa na tovuti hiyo haingeweza kurejeshwa kiotomatiki; ungelazimika kuwasiliana na Usaidizi wa Babilim kupitia %2$s. Ili kuhifadhi utambulisho, bofya Ghairi, ondoa tiki kwenye "Futa data yote ya Babilim wakati wa kusanidua" katika Mipangilio ya Babilim ya tovuti hiyo, kisha uzime tena. Zima hata hivyo?' . "\0" . 'Tovuti %1$d kwenye mtandao huu zimewekwa kufuta utambulisho wao wa Babilim programu-jalizi itakapofutwa. Leseni za kulipia zilizounganishwa na tovuti hizo haziwezi kurejeshwa kiotomatiki; ungelazimika kuwasiliana na Usaidizi wa Babilim kupitia %2$s. Ili kuhifadhi utambulisho, bofya Ghairi, ondoa tiki kwenye "Futa data yote ya Babilim wakati wa kusanidua" katika Mipangilio ya Babilim ya kila tovuti, kisha uzime tena. Zima hata hivyo?','%1$s %2$s.'=>'%1$s %2$s.','%1$s (%2$s): %3$s'=>'%1$s (%2$s): %3$s','%1$s nothing to do.'=>'%1$s hakuna cha kufanya.','%1$s: %2$s'=>'%1$s: %2$s','%1$s: %2$s (%3$s)'=>'%1$s: %2$s (%3$s)','%1$s: %2$s. Choose the language.'=>'%1$s: %2$s. Chagua lugha.','%d failed'=>'%d imeshindwa' . "\0" . '%d imeshindwa','%d not yet tried'=>'%d bado haijajaribiwa' . "\0" . '%d bado haijajaribiwa','%d report is waiting. "Always share" and "Don\'t share" apply to all of them.'=>'Ripoti %d inasubiri. "Shiriki kila wakati" na "Usishiriki" zinatumika kwa zote.' . "\0" . 'Ripoti %d zinasubiri. "Shiriki kila wakati" na "Usishiriki" zinatumika kwa zote.','%d skipped'=>'%d imerukwa' . "\0" . '%d imerukwa','%d succeeded'=>'%d imefanikiwa' . "\0" . '%d imefanikiwa','%d to install'=>'%d ya kusakinisha' . "\0" . '%d za kusakinisha','(a public key generated for this site)'=>'(ufunguo wa umma uliozalishwa kwa ajili ya tovuti hii)','(detected)'=>'(imegunduliwa)','(generic codes and coordinates only)'=>'(misimbo ya jumla na viwianishi pekee)','A cleanup was paused on %1$s: %2$s. Nothing was deleted.'=>'Usafishaji ulisitishwa tarehe %1$s: %2$s. Hakuna kilichofutwa.','A file in the component could not be read, so it was not packaged.'=>'Faili moja katika kijenzi haikuweza kusomwa, kwa hivyo haikufungashwa.','A host that serves only one PHP request at a time cannot complete this step.'=>'Mwenyeji anayehudumia ombi moja tu la PHP kwa wakati mmoja hawezi kukamilisha hatua hii.','A part of the upload kept failing, so the upload was cancelled.'=>'Sehemu ya upakiaji iliendelea kushindwa, kwa hivyo upakiaji ulighairiwa.','A translation cannot be requested for that locale on this site right now.'=>'Tafsiri haiwezi kuombwa kwa lugha hiyo kwenye tovuti hii kwa sasa.','A translation-index write conflicted with another request on %1$s (%2$s) and was not applied; the most recent version was kept.'=>'Uandishi wa faharasa ya tafsiri uligongana na ombi lingine tarehe %1$s (%2$s) na haukutekelezwa; toleo la hivi karibuni zaidi lilihifadhiwa.','A translation-index write on %1$s (%2$s) could not be completed and was not applied (%3$s).'=>'Uandishi wa faharasa ya tafsiri tarehe %1$s (%2$s) haukukamilika na haukutekelezwa (%3$s).','Account'=>'Akaunti','Add another language'=>'Ongeza lugha nyingine','Advanced'=>'Mipangilio ya hali ya juu','All'=>'Vyote','All free-plan slots for this site are used'=>'Nafasi zote za mpango wa bure za tovuti hii zimetumika','All languages'=>'Lugha zote','Already in WordPress core'=>'Tayari ipo kwenye kiini cha WordPress','Already installed.'=>'Tayari imesakinishwa.','Always share'=>'Shiriki kila wakati','Another installation is running; try again in a moment.'=>'Usakinishaji mwingine unaendelea; jaribu tena baada ya muda mfupi.','Automatic installs'=>'Usakinishaji otomatiki','Automatic installs are now off; turn them on again in the settings if you want them.'=>'Usakinishaji wa kiotomatiki sasa umezimwa; uwashe tena kwenye mipangilio ukitaka.','Available'=>'Zinazopatikana','Available translations can be installed with one click, and missing ones can be requested. While automatic installs are on, translations the service lists as available for the languages you manage are installed during the twice-daily sync.'=>'Tafsiri zinazopatikana zinaweza kusakinishwa kwa mbofyo mmoja, na zile zinazokosekana zinaweza kuombwa. Usakinishaji otomatiki ukiwa umewashwa, tafsiri ambazo huduma inaorodhesha kuwa zinapatikana kwa lugha unazozisimamia husakinishwa wakati wa usawazishaji mara mbili kwa siku.','Available · %s'=>'Inapatikana · %s','Babilim Settings'=>'Mipangilio ya Babilim','Babilim adds translations for every language checked here.'=>'Babilim huongeza tafsiri za kila lugha iliyotiwa alama hapa.','Babilim could not confirm a temporary folder outside the website, so the component was not packaged and nothing was uploaded. Define BABILIM_TEMP_DIR in wp-config.php as a writable folder outside the web root (for example a folder next to, not inside, your site\'s public directory), or ask your host for one.'=>'Babilim haikuweza kuthibitisha folda ya muda nje ya tovuti, kwa hiyo kijenzi hakikufungashwa na hakuna kilichopakiwa. Bainisha BABILIM_TEMP_DIR katika wp-config.php kama folda inayoweza kuandikwa nje ya mzizi wa wavuti (kwa mfano folda iliyo kando ya, si ndani ya, saraka ya umma ya tovuti yako), au mwombe mwenyeji wako akupe moja.','Babilim could not finish checking this site.'=>'Babilim haikuweza kumaliza kukagua tovuti hii.','Babilim could not finish enabling (%1$s): %2$s'=>'Babilim haikuweza kukamilisha kuwezesha (%1$s): %2$s','Babilim could not finish verifying this site (the service could not reach it back). Registration is paused.'=>'Babilim haikuweza kukamilisha uthibitishaji wa tovuti hii (huduma haikuweza kuifikia tena). Usajili umesitishwa.','Babilim could not verify this site, so nothing is downloaded or installed until verification succeeds.'=>'Babilim haikuweza kuthibitisha tovuti hii, kwa hivyo hakuna kitakachopakuliwa wala kusakinishwa hadi uthibitishaji ufanikiwe.','Babilim could not verify this site, so nothing is downloaded or installed.'=>'Babilim haikuweza kuthibitisha tovuti hii, kwa hivyo hakuna kinachopakuliwa wala kusakinishwa.','Babilim finds the plugins and themes on this site that have no translation for your language and installs one for each.'=>'Babilim hupata programu-jalizi na mandhari kwenye tovuti hii ambazo hazina tafsiri ya lugha yako na husakinisha moja kwa kila moja.','Babilim has not been enabled for this site yet.'=>'Babilim haijawashwa kwa tovuti hii bado.','Babilim has not installed any translation for this language.'=>'Babilim haijasakinisha tafsiri yoyote kwa lugha hii.','Babilim hit an error. Share an error report?'=>'Babilim imekumbwa na hitilafu. Shiriki ripoti ya hitilafu?','Babilim installed %d translation automatically since your last visit.'=>'Babilim imesakinisha tafsiri %d kiotomatiki tangu ziara yako ya mwisho.' . "\0" . 'Babilim imesakinisha tafsiri %d kiotomatiki tangu ziara yako ya mwisho.','Babilim is disabled. Nothing more is sent; translations already installed keep working.'=>'Babilim imezimwa. Hakuna kitakachotumwa tena; tafsiri zilizosakinishwa tayari zinaendelea kufanya kazi.','Babilim is enabled: this site is verified and %d component was found.'=>'Babilim imewashwa: tovuti hii imethibitishwa na kijenzi %d kimepatikana.' . "\0" . 'Babilim imewashwa: tovuti hii imethibitishwa na vijenzi %d vimepatikana.','Babilim is enabling and checking this site… (last attempt: %s)'=>'Babilim inawezesha na kukagua tovuti hii… (jaribio la mwisho: %s)','Babilim is enabling and checking this site… Reload this page or wait for the scheduled check to finish.'=>'Babilim inawezesha na kukagua tovuti hii… Pakia upya ukurasa huu au subiri ukaguzi uliopangwa ukamilike.','Babilim is not enabled.'=>'Babilim haijawashwa.','Babilim is set to erase this site\'s identity when the plugin is deleted. The paid license attached to this site could then not be restored automatically; you would have to contact Babilim support at %s. To keep the identity, press Cancel, untick "Delete all Babilim data on uninstall" in the Babilim settings, and deactivate again. Deactivate anyway?'=>'Babilim imewekwa kufuta utambulisho wa tovuti hii programu-jalizi itakapofutwa. Leseni ya kulipia iliyounganishwa na tovuti hii haingeweza kurejeshwa kiotomatiki; ungelazimika kuwasiliana na Usaidizi wa Babilim kupitia %s. Ili kuhifadhi utambulisho, bofya Ghairi, ondoa tiki kwenye "Futa data yote ya Babilim wakati wa kusanidua" katika Mipangilio ya Babilim, kisha uzime tena. Zima hata hivyo?','Babilim ran out of time for this step and will continue on the next check.'=>'Babilim imeishiwa na muda kwa hatua hii na itaendelea katika ukaguzi unaofuata.','Babilim settings'=>'Mipangilio ya Babilim','Babilim sync is temporarily delayed by the service (rate limited); it will try again after %s.'=>'Usawazishaji wa Babilim umecheleweshwa kwa muda na huduma (kikomo cha kasi); utajaribu tena baada ya %s.','Babilim was updated while this upload was waiting. The old package was discarded; please confirm the upload again.'=>'Babilim ilisasishwa wakati upakiaji huu ulikuwa unasubiri. Kifurushi cha zamani kilitupwa; tafadhali thibitisha upakiaji tena.','Babilim will upload these files from %1$s (version %2$s): every .php and .js file, every block.json file, and the readme.txt, readme.md, style.css and theme.json in its main folder. They are used to find the text that needs translating and to identify the plugin or theme.'=>'Babilim itapakia faili hizi kutoka %1$s (toleo %2$s): kila faili ya .php na .js, kila faili ya block.json, na readme.txt, readme.md, style.css na theme.json katika folda kuu yake. Hutumiwa kupata maandishi yanayohitaji kutafsiriwa na kutambua programu jalizi au mandhari.','Babilim_Manifest is unavailable: %s'=>'Babilim_Manifest haipatikani: %s','Back'=>'Rudi','Bought a license for this domain before? Enter the restore code you received at checkout.'=>'Ulishanunua leseni ya kikoa hiki? Weka msimbo wa kurejesha uliopokea wakati wa malipo.','Broken placeholder'=>'Kishikilia nafasi kimeharibika','Build'=>'Toleo la kifurushi','Built'=>'Imejengwa','Bulk actions apply only to the selected language of each selected component.'=>'Vitendo vya wingi vinatumika tu kwa lugha iliyochaguliwa ya kila kijenzi kilichochaguliwa.','Bulk actions apply to every matching language of each selected component.'=>'Vitendo vya wingi vinatumika kwa kila lugha inayolingana ya kila kijenzi kilichochaguliwa.','Bulk download:'=>'Upakuaji wa pamoja:','Bulk request:'=>'Ombi la pamoja:','Bulk update:'=>'Sasisho la pamoja:','Bundled with the plugin'=>'Imejumuishwa na programu-jalizi','Bundled with the theme'=>'Imejumuishwa na mandhari','By clicking Enable, you agree to send the information listed above to Babilim.'=>'Kwa kubofya Wezesha, unakubali kutuma taarifa zilizoorodheshwa hapo juu kwa Babilim.','By continuing you confirm that you have the right to upload this component.'=>'Kwa kuendelea unathibitisha kwamba una haki ya kupakia kijenzi hiki.','Cancel'=>'Ghairi','Category'=>'Kategoria','Check again'=>'Angalia tena','Check again now'=>'Angalia tena sasa','Checkout is not available for this site right now.'=>'Malipo hayapatikani kwa tovuti hii kwa sasa.','Choose'=>'Chagua','Choose a category…'=>'Chagua kategoria…','Choose a language'=>'Chagua lugha','Choose a language…'=>'Chagua lugha…','Clear filters'=>'Futa vichujio','Close'=>'Funga','Component'=>'Kijenzi','Confirm'=>'Thibitisha','Conflicting keys'=>'Funguo zinazogongana','Continue'=>'Endelea','Continue next batch (%d left)'=>'Endelea na kundi linalofuata (zimebaki %d)','Continuing…'=>'Inaendelea…','Could not back up %s before replacing it.'=>'Imeshindwa kuhifadhi nakala ya %s kabla ya kuibadilisha.','Could not create the package archive.'=>'Imeshindwa kuunda faili ya kifurushi.','Could not determine active components; the existing merged index was left unchanged.'=>'Imeshindwa kubaini vijenzi vinavyotumika; faharasa iliyounganishwa iliyopo haikubadilishwa.','Could not determine installed plugins/themes; sweep skipped, nothing was deleted.'=>'Haikuweza kubaini programu-jalizi/mandhari zilizosakinishwa; usafishaji umerukwa, hakuna kilichofutwa.','Could not load the full WordPress.org locale list from the service, so no other language can be added right now.'=>'Imeshindwa kupakia orodha kamili ya lugha za WordPress.org kutoka kwenye huduma, kwa hivyo hakuna lugha nyingine inayoweza kuongezwa sasa.','Could not move %s into place.'=>'Imeshindwa kuhamisha %s mahali pake.','Could not move the merged index for \'%s\' into place; the previous served index (if any) was removed rather than left half-updated. No default-domain supplement is served for this locale until the next successful rebuild.'=>'Haikuweza kuweka faharasa iliyounganishwa ya \'%s\' mahali pake; faharasa iliyotumika awali (kama ipo) iliondolewa badala ya kuachwa nusu-imesasishwa. Hakuna nyongeza ya default domain inayotolewa kwa lugha hii hadi ujenzi upya utakaofanikiwa.','Could not open zip: %s'=>'Imeshindwa kufungua zip: %s','Could not prepare %s for rollback.'=>'Imeshindwa kuandaa %s kwa kurudisha toleo la awali.','Could not read %s back after moving it into place.'=>'Imeshindwa kusoma %s tena baada ya kuihamishia mahali pake.','Could not read: %s'=>'Imeshindwa kusoma: %s','Could not restore the purchase: %s'=>'Imeshindwa kurejesha ununuzi: %s','Could not show a new restore code: %s'=>'Imeshindwa kuonyesha msimbo mpya wa kurejesha: %s','Could not stage %s'=>'Imeshindwa kuandaa %s','Could not stage default/%s'=>'Imeshindwa kuandaa default/%s','Could not start checkout: %s'=>'Imeshindwa kuanzisha malipo: %s','Could not verify entry count for %s'=>'Imeshindwa kuthibitisha idadi ya maingizo kwa %s','Could not write the downloaded package to disk.'=>'Imeshindwa kuandika kifurushi kilichopakuliwa kwenye diski.','Could not write the staged merged index.'=>'Haikuweza kuandika faharasa iliyounganishwa ya maandalizi.','Current translation'=>'Tafsiri ya sasa','Custom overrides'=>'Mbadala maalum','Danger zone'=>'Eneo la hatari','Default supplement entry count mismatch.'=>'Idadi ya maingizo ya nyongeza chaguomsingi hailingani.','Delete all Babilim data on uninstall'=>'Futa data yote ya Babilim wakati wa kusanidua','Disable Babilim'=>'Zima Babilim','Disable Babilim? Installed translations are kept, but no further checks or downloads will run.'=>'Zima Babilim? Tafsiri zilizosakinishwa zitabaki, lakini hakuna ukaguzi wala upakuaji utakaoendelea.','Don\'t share'=>'Usishiriki','Download'=>'Pakua','Downloaded and installed.'=>'Imepakuliwa na kusakinishwa.','Downloading…'=>'Inapakua…','Downloads: %1$d/%2$d (%3$s)'=>'Upakuaji: %1$d/%2$d (%3$s)','Each component\'s own contribution to each locale\'s shared default-domain supplement.'=>'Mchango wa kila kijenzi kwenye nyongeza ya default domain inayoshirikiwa ya kila lugha.','Enable Babilim'=>'Washa Babilim','Enabling…'=>'Inawezesha…','English (United States)'=>'Kiingereza (Marekani)','Entries'=>'Ingizo','Entry count mismatch for %s'=>'Idadi ya maingizo hailingani kwa %s','Error reports'=>'Ripoti za hitilafu','Every installed plugin/theme: its slug, version, text domain(s), whether it\'s a wp.org listing, its own bundled locales, and which locales you\'ve already installed a Babilim translation for.'=>'Kila programu-jalizi/mandhari iliyosakinishwa: slug yake, toleo, maandishi ya domain (text domain), kama imeorodheshwa wp.org, locale zake zilizojumuishwa, na locale ambazo tayari umesakinisha tafsiri ya Babilim kwa ajili yazo.','Every locale in use on this site (site locale, installed language packs, user locales, and any you add manually). No locale is treated differently from another.'=>'Kila locale inayotumika kwenye tovuti hii (locale ya tovuti, vifurushi vya lugha vilivyosakinishwa, locale za watumiaji, na zozote unazoongeza mwenyewe). Hakuna locale inayotendewa tofauti na nyingine.','Excluded'=>'Imeondolewa','Files with other names or extensions are not included, nor are the uploads, cache, logs, backup, data, vendor, node_modules and languages folders, hidden files, or files whose names match common secrets (wp-config*, .env*, *.sql, *.log, *.pem, *.key). Code files can still contain text or data you would not want to share; check them if you are unsure. The service removes the same kinds of files again on arrival.'=>'Faili zenye majina au viendelezi vingine hazijajumuishwa, wala folda za uploads, cache, logs, backup, data, vendor, node_modules na languages, faili zilizofichwa, au faili ambazo majina yake yanalingana na siri za kawaida (wp-config*, .env*, *.sql, *.log, *.pem, *.key). Faili za msimbo bado zinaweza kuwa na maandishi au data ambazo hungependa kushiriki; zikague ikiwa huna uhakika. Huduma huondoa aina hizo hizo za faili tena inapozipokea.','Free'=>'Bila malipo','Free-plan slots'=>'Nafasi za mpango wa bure','General'=>'Jumla','If this is on, uninstalling also erases this site\'s identity. The paid license attached to this site cannot be restored automatically afterwards; you would have to contact Babilim support at %s to get it back.'=>'Ikiwa hii imewashwa, kusanidua pia kunafuta utambulisho wa tovuti hii. Leseni ya kulipia iliyounganishwa na tovuti hii haiwezi kurejeshwa kiotomatiki baadaye; utalazimika kuwasiliana na Usaidizi wa Babilim kupitia %s ili kuipata tena.','Included'=>'Imejumuishwa','Included in index'=>'Imejumuishwa kwenye faharasa','Install available translations automatically'=>'Sakinisha tafsiri zilizopo kiotomatiki','Installed'=>'Zilizosakinishwa','Installed translations are kept, but no further checks or downloads will run.'=>'Tafsiri zilizosakinishwa huhifadhiwa, lakini hakutakuwa na ukaguzi wala upakuaji zaidi.','Installed · %s'=>'Imesakinishwa · %s','Installed · built for %1$s, this site has %2$s'=>'Imesakinishwa · imejengwa kwa %1$s, tovuti hii ina %2$s','Installed · built for %s'=>'Imesakinishwa · imejengwa kwa %s','Installed · built for %s, all free-plan slots for this site are used'=>'Imesakinishwa · imetengenezwa kwa %s, nafasi zote za mpango wa bure za tovuti hii zimetumika','Installed · built for %s, new version failed'=>'Imesakinishwa · imejengwa kwa %s, toleo jipya limeshindwa','Installed · built for %s, new version not covered by the free service plan'=>'Imesakinishwa · imetengenezwa kwa %s, toleo jipya halijajumuishwa katika mpango wa huduma wa bure','Installed · built for %s, new version scheduled'=>'Imesakinishwa · imejengwa kwa %s, toleo jipya limepangwa','Installed · built for %s, translating the new version…'=>'Imesakinishwa · imejengwa kwa %s, inatafsiri toleo jipya…','Installed · built for a different version'=>'Imesakinishwa · imejengwa kwa toleo tofauti','Installed · built for a different version, all free-plan slots for this site are used'=>'Imesakinishwa · imetengenezwa kwa toleo tofauti, nafasi zote za mpango wa bure za tovuti hii zimetumika','Installed · built for a different version, new version failed'=>'Imesakinishwa · imejengwa kwa toleo tofauti, toleo jipya limeshindwa','Installed · built for a different version, new version not covered by the free service plan'=>'Imesakinishwa · imetengenezwa kwa toleo tofauti, toleo jipya halijajumuishwa katika mpango wa huduma wa bure','Installed · built for a different version, new version scheduled'=>'Imesakinishwa · imejengwa kwa toleo tofauti, toleo jipya limepangwa','Installed · built for a different version, translating the new version…'=>'Imesakinishwa · imejengwa kwa toleo tofauti, inatafsiri toleo jipya…','It is stored by the service\'s hosting provider and processed by AI models to produce the translation.'=>'Huhifadhiwa na mtoa huduma wa upangishaji wa huduma hiyo na kuchakatwa na miundo ya AI ili kutoa tafsiri.','Keep my own translation overrides when purging everything or uninstalling this plugin.'=>'Weka mbadala zangu za tafsiri wakati wa kufuta kila kitu au kusanidua programu-jalizi hii.','Language'=>'Lugha','Language:'=>'Lugha:','Languages'=>'Lugha','Languages found on this site: %s.'=>'Lugha zilizopatikana kwenye tovuti hii: %s.','Last cleanup on %1$s: %2$d newly marked, %3$d file(s) deleted, %4$d record(s) removed.'=>'Usafishaji wa mwisho tarehe %1$s: %2$d zimewekwa alama mpya, faili %3$d zimefutwa, rekodi %4$d zimeondolewa.','Maintenance'=>'Matengenezo','Maintenance status is not available right now.'=>'Hali ya matengenezo haipatikani kwa sasa.','Manifest unavailable: %s'=>'Manifest haipatikani: %s','Negation reversed'=>'Ukanushi umegeuzwa','No'=>'Hapana','No build is available to download for this locale.'=>'Hakuna toleo linalopatikana la kupakua kwa lugha hii.','No cleanup has run yet.'=>'Hakuna usafishaji uliofanyika bado.','No components match these filters. %s'=>'Hakuna vijenzi vinavyolingana na vichujio hivi. %s','No components synced yet.'=>'Hakuna vijenzi vilivyosawazishwa bado.','No installed translation matches.'=>'Hakuna tafsiri iliyosakinishwa inayolingana.','No language is managed yet.'=>'Hakuna lugha inayosimamiwa bado.','No pending challenge for this nonce.'=>'Hakuna changamoto inayosubiri kwa nonce hii.','No pending challenge to verify.'=>'Hakuna changamoto inayosubiri kuthibitishwa.','No plugins or themes found.'=>'Hakuna programu-jalizi au mandhari zilizopatikana.','No previous build to roll back to.'=>'Hakuna toleo la awali la kurudishia.','No record for %s'=>'Hakuna rekodi ya %s','No site id is on file to rotate a token for.'=>'Hakuna kitambulisho cha tovuti kwenye faili cha kubadilishia tokeni.','No — component inactive'=>'Hapana — kijenzi hakitumiki','No — component removed'=>'Hapana — kijenzi kimeondolewa','No — installed version differs from the active one'=>'Hapana — toleo lililosakinishwa ni tofauti na lile linalotumika','Not a valid server_build_id: %s'=>'Si server_build_id halali: %s','Not covered by the free service plan'=>'Haijajumuishwa katika mpango wa huduma wa bure','Not installed'=>'Haijasakinishwa','Not registered yet'=>'Bado haijasajiliwa','Not supported'=>'Haitumiki','Not verified'=>'Haijathibitishwa','Note (optional)'=>'Maelezo (si lazima)','Nothing to choose.'=>'Hakuna cha kuchagua.','Nothing to confirm.'=>'Hakuna cha kuthibitisha.','Off by default: deleting the plugin keeps this site\'s identity, so a reinstall can reuse it.'=>'Imezimwa kwa chaguo-msingi: kufuta programu-jalizi huhifadhi utambulisho wa tovuti hii, ili usakinishaji upya uutumie tena.','One or more served files no longer match the manifest.'=>'Faili moja au zaidi zinazotolewa hazilingani tena na manifest.','One-time purchase for this site: %1$s %2$s. Includes all future translation updates. Payment is handled by Paddle in a new tab.'=>'Ununuzi wa mara moja kwa tovuti hii: %1$s %2$s. Unajumuisha masasisho yote ya tafsiri yajayo. Malipo yanashughulikiwa na Paddle kwenye kichupo kipya.','Only a network administrator can do this, because it changes translation files shared by every site on this network.'=>'Ni msimamizi wa mtandao pekee anayeweza kufanya hivi, kwa sababu hubadilisha faili za tafsiri zinazoshirikiwa na kila tovuti kwenye mtandao huu.','Only plugins and themes can be packaged.'=>'Programu-jalizi na mandhari pekee ndizo zinazoweza kufungashwa.','Only when you confirm an upload for a plugin or theme that is not on WordPress.org: every .php and .js file, every block.json file, and the readme.txt, readme.md, style.css and theme.json in that component\'s main folder, as a zip, after files that match common secrets are left out.'=>'Ni pale tu unapothibitisha upakiaji wa programu jalizi au mandhari ambayo haipo kwenye WordPress.org: kila faili ya .php na .js, kila faili ya block.json, na readme.txt, readme.md, style.css na theme.json katika folda kuu ya kijenzi hicho, kama zip, baada ya faili zinazolingana na siri za kawaida kuachwa.','Open Babilim settings'=>'Fungua mipangilio ya Babilim','Original language'=>'Lugha asili','Original string'=>'Maandishi asili','Paid'=>'Ya kulipia','Partner'=>'Mshirika','Please check that your site can be reached from the internet, then try again.'=>'Tafadhali hakikisha tovuti yako inaweza kufikiwa kutoka mtandaoni, kisha ujaribu tena.','Please choose a category for this report.'=>'Tafadhali chagua kategoria ya ripoti hii.','Plugin'=>'Programu-jalizi','Plugin · %s'=>'Programu-jalizi · %s','Plugins'=>'Programu-jalizi','Preview'=>'Hakiki','Purchase restored. This site is now licensed.'=>'Ununuzi umerejeshwa. Tovuti hii sasa ina leseni.','Re-parsed entry count did not match the built index.'=>'Idadi ya maingizo yaliyochanganuliwa upya haikulingana na faharasa iliyojengwa.','Re-verify'=>'Thibitisha upya','Rebuild index now'=>'Jenga upya faharasa sasa','Refusing to write outside the Babilim language-file directory.'=>'Inakataa kuandika nje ya saraka ya faili za lugha za Babilim.','Registration response was missing required fields.'=>'Jibu la usajili halikuwa na sehemu zinazohitajika.','Registration restarted.'=>'Usajili umeanzishwa upya.','Remove'=>'Ondoa','Remove everything Babilim installed'=>'Ondoa kila kitu ambacho Babilim ilisakinisha','Remove everything Babilim installed? This deletes every language file it installed for every plugin and theme on this site.'=>'Ungependa kuondoa kila kitu ambacho Babilim ilisakinisha? Hii inafuta kila faili la lugha lililosakinishwa na Babilim kwa kila programu-jalizi na mandhari kwenye tovuti hii.','Remove the %2$s translation of %1$s from this site?'=>'Ondoa tafsiri ya %2$s ya %1$s kwenye tovuti hii?','Removed %d installed component.'=>'Kijenzi %d kilichosakinishwa kimeondolewa.' . "\0" . 'Vijenzi %d vilivyosakinishwa vimeondolewa.','Removed after a failed integrity check'=>'Imeondolewa baada ya ukaguzi wa uadilifu kushindwa','Removed.'=>'Imeondolewa.','Removes every language file Babilim has installed for every plugin and theme on this site.'=>'Huondoa kila faili la lugha ambalo Babilim limesakinisha kwa kila programu-jalizi na mandhari kwenye tovuti hii.','Report a problem'=>'Ripoti tatizo','Report translation'=>'Ripoti tafsiri','Request newer translation'=>'Omba tafsiri mpya zaidi','Request translation'=>'Omba tafsiri','Requestable'=>'Inaweza kuombwa','Requesting…'=>'Inaomba…','Restart registration'=>'Anzisha upya usajili','Restore code'=>'Msimbo wa kurejesha','Restore purchase'=>'Rejesha ununuzi','Retry request'=>'Jaribu tena ombi','Roll back'=>'Rudisha nyuma','Roll back and report'=>'Rudisha nyuma na uripoti','Roll back and send report'=>'Rudisha nyuma na utume ripoti','Roll back the %2$s translation of %1$s to the previous build?'=>'Rudisha tafsiri ya %2$s ya %1$s kwenye muundo uliotangulia?','Rolled back and reported.'=>'Imerudishwa nyuma na kuripotiwa.','Rolled back to the previous build.'=>'Imerudishwa kwenye toleo la awali.','Rolled back, but the report could not be sent: %s'=>'Imerudishwa nyuma, lakini ripoti haikuweza kutumwa: %s','Rolling back would overwrite \'%1$s\' (%2$s), which is now served for another installed component (%3$s); nothing was changed.'=>'Kurudisha toleo la awali kungeandika juu ya \'%1$s\' (%2$s), ambayo sasa inatolewa kwa kijenzi kingine kilichosakinishwa (%3$s); hakuna kilichobadilishwa.','Rotate-token response was missing site_token.'=>'Jibu la kubadilisha tokeni halikuwa na site_token.','Save changes'=>'Hifadhi mabadiliko','Scheduled, waiting to be processed'=>'Imepangwa, inasubiri kushughulikiwa','Search'=>'Tafuta','Search components'=>'Tafuta vijenzi','Search the installed translations'=>'Tafuta katika tafsiri zilizosakinishwa','Select all'=>'Chagua vyote','Select fewer components: at most %1$d operations per run (you selected %2$d).'=>'Chagua vijenzi vichache zaidi: upeo wa shughuli %1$d kwa kila uendeshaji (umechagua %2$d).','Send report'=>'Tuma ripoti','Service plan'=>'Mpango wa huduma','Settings'=>'Mipangilio','Share error reports'=>'Shiriki ripoti za hitilafu','Share this report'=>'Shiriki ripoti hii','Show a new restore code'=>'Onyesha msimbo mpya wa kurejesha','Show the "Report translation" entry in the admin toolbar'=>'Onyesha kipengee cha "Ripoti tafsiri" kwenye upau wa zana wa msimamizi','Some of this component\'s text is hard-coded by its author and can\'t be translated by a language pack.'=>'Baadhi ya maandishi ya kijenzi hiki yameandikwa moja kwa moja na mwandishi wake na hayawezi kutafsiriwa na kifurushi cha lugha.','Status'=>'Hali','Status unknown'=>'Hali haijulikani','String context'=>'Muktadha wa mfuatano wa maneno','Suggested translation'=>'Tafsiri inayopendekezwa','Supplementary translation index'=>'Faharasa ya tafsiri za ziada','Supplementary translation index rebuilt.'=>'Faharasa ya tafsiri ya ziada imejengwa upya.','Supplementary translation maintenance'=>'Matengenezo ya tafsiri za ziada','Supplementary translations'=>'Tafsiri za ziada','Sweep aborted without orphaning anything: %s.'=>'Usafishaji umesitishwa bila kufanya chochote kuwa yatima: %s.','Sweep complete: %d file deleted.'=>'Usafishaji umekamilika: faili %d imefutwa.' . "\0" . 'Usafishaji umekamilika: faili %d zimefutwa.','Sweep now'=>'Safisha sasa','Sync complete.'=>'Usawazishaji umekamilika.','Thank you. Your report was sent.'=>'Asante. Ripoti yako imetumwa.','That component is not installed on this site, so a translation cannot be requested for it.'=>'Kijenzi hicho hakijasakinishwa kwenye tovuti hii, kwa hivyo tafsiri haiwezi kuombwa kwa ajili yake.','That does not look like a restore code.'=>'Hii haionekani kuwa msimbo wa kurejesha.','That is not a valid WordPress locale code. Nothing was saved.'=>'Hiyo si msimbo halali wa lugha wa WordPress. Hakuna kilichohifadhiwa.','That is not a valid build identifier.'=>'Hicho si kitambulisho cha muundo halali.','The change could not be recorded in the translation index; please try again.'=>'Mabadiliko hayakuweza kurekodiwa kwenye faharasa ya tafsiri; tafadhali jaribu tena.','The cleanup ran, but some of its changes could not be recorded in the translation index; the next cleanup will retry them.'=>'Usafishaji ulifanyika, lakini baadhi ya mabadiliko yake hayakuweza kurekodiwa kwenye faharasa ya tafsiri; usafishaji ujao utayajaribu tena.','The component has no files that can be uploaded.'=>'Kijenzi hakina faili zinazoweza kupakiwa.','The component is not inside the plugins or themes directory.'=>'Kijenzi hakipo ndani ya saraka ya programu-jalizi au mandhari.','The component\'s main file was not found.'=>'Faili kuu ya kijenzi haikupatikana.','The download response was missing a usable location.'=>'Jibu la upakuaji halikuwa na eneo linaloweza kutumika.','The entry opens a panel to search the translations Babilim installed on this site and report one of them.'=>'Kipengee hiki hufungua paneli ya kutafuta tafsiri ambazo Babilim ilisakinisha kwenye tovuti hii na kuripoti mojawapo.','The field "%1$s" is too long: it has %2$d characters and the limit is %3$d. Nothing was sent; please shorten it and try again.'=>'Sehemu "%1$s" ni ndefu mno: ina herufi %2$d na kikomo ni %3$d. Hakuna kilichotumwa; tafadhali ifupishe na ujaribu tena.','The given domain \'%1$s\' matches neither the package manifest\'s own slug \'%2$s\' nor its text_domain \'%3$s\'.'=>'Domain iliyotolewa \'%1$s\' hailingani na slug ya package manifest \'%2$s\' wala text_domain yake \'%3$s\'.','The merged index for \'%s\' was rebuilt, but the translation index could not record it; the next rebuild will retry.'=>'Faharasa iliyounganishwa ya \'%s\' ilijengwa upya, lakini faharasa ya tafsiri haikuweza kuirekodi; ujenzi upya ujao utajaribu tena.','The original text and the translations made from it will be provided to other sites that install the same version.'=>'Maandishi asili na tafsiri zilizotengenezwa kutoka kwayo zitatolewa kwa tovuti nyingine zinazosakinisha toleo lilelile.','The package declares no main translation file.'=>'Kifurushi hakijatangaza faili kuu ya tafsiri.','The package has no %s for its own text domain.'=>'Kifurushi hakina %s kwa ajili ya text domain yake yenyewe.','The package manifest\'s kind \'%1$s\' does not match the requested kind \'%2$s\'.'=>'Aina \'%1$s\' ya package manifest hailingani na aina iliyoombwa \'%2$s\'.','The package produced no servable main translation file.'=>'Kifurushi hakikutoa faili kuu ya tafsiri inayoweza kutolewa.','The package\'s text domain \'%1$s\' does not match this site\'s copy of the component (\'%2$s\'), so it was not installed.'=>'Maandishi ya domain (text domain) ya kifurushi \'%1$s\' hayalingani na nakala ya kijenzi kwenye tovuti hii (\'%2$s\'), kwa hivyo hakikusakinishwa.','The packaged component could not be read.'=>'Kijenzi kilichofungashwa hakikuweza kusomwa.','The registration challenge is not in the expected form.'=>'Changamoto ya usajili haiko katika umbo linalotarajiwa.','The report could not be sent.'=>'Ripoti haikuweza kutumwa.','The search could not be completed.'=>'Utafutaji haukuweza kukamilika.','The service asked this site to wait before syncing again.'=>'Huduma iliomba tovuti hii isubiri kabla ya kusawazisha tena.','The service could not reach your site. A firewall, security plugin or host rule is probably blocking the request; please allow requests to /wp-json/babilim/v1/challenge.'=>'Huduma haikuweza kufikia tovuti yako. Huenda ngome ya moto, programu-jalizi ya usalama au sheria ya mwenyeji inazuia ombi; tafadhali ruhusu maombi kwenda /wp-json/babilim/v1/challenge.','The service\'s upload offer was incomplete.'=>'Ofa ya upakiaji ya huduma haikukamilika.','The text domain \'%1$s\' (%2$s) is already served for another installed component (%3$s); nothing was installed.'=>'Text domain \'%1$s\' (%2$s) tayari inatolewa kwa kijenzi kingine kilichosakinishwa (%3$s); hakuna kilichosakinishwa.','The upload is kept until you ask Babilim to delete it.'=>'Upakiaji huhifadhiwa hadi utakapoomba Babilim iufute.','Theme'=>'Mandhari','Theme · %s'=>'Mandhari · %s','Themes'=>'Mandhari','There is no upload in progress.'=>'Hakuna upakiaji unaoendelea.','There is no upload waiting for confirmation.'=>'Hakuna upakiaji unaosubiri uthibitisho.','These are the languages this site uses. You can change them in %s.'=>'Hizi ndizo lugha zinazotumiwa na tovuti hii. Unaweza kuzibadilisha katika %s.','These fields will be sent:'=>'Sehemu hizi zitatumwa:','This build is not one this site currently knows about for this component/locale.'=>'Toleo hili si moja ambalo tovuti hii inalifahamu kwa sasa kwa kijenzi/lugha hii.','This component does not declare a version number, so a translation cannot be requested for it.'=>'Kijenzi hiki hakitaji nambari ya toleo, kwa hivyo tafsiri haiwezi kuombwa kwa ajili yake.','This component is larger than the service accepts, so it cannot be uploaded.'=>'Kijenzi hiki ni kikubwa kuliko huduma inavyokubali, kwa hivyo hakiwezi kupakiwa.','This component was already uploaded. Babilim is checking it now.'=>'Kijenzi hiki kilishapakiwa. Babilim kinakikagua sasa.','This component\'s version number is longer than %d characters, which Babilim cannot handle, so a translation cannot be requested for it.'=>'Nambari ya toleo la kijenzi hiki ni ndefu kuliko herufi %d, jambo ambalo Babilim haiwezi kulishughulikia, kwa hivyo tafsiri haiwezi kuombwa kwa ajili yake.','This issues a new restore code and the previous one stops working. Continue?'=>'Hii inatoa msimbo mpya wa kurejesha na ule wa awali utaacha kufanya kazi. Endelea?','This network has too many sites to check them one by one, and some of them may be set to erase their Babilim identity when the plugin is deleted. The paid license attached to such a site could then not be restored automatically; you would have to contact Babilim support at %s. To keep the identities, press Cancel, untick "Delete all Babilim data on uninstall" in each site\'s Babilim settings, and deactivate again. Deactivate anyway?'=>'Mtandao huu una tovuti nyingi mno kuzikagua moja baada ya nyingine, na baadhi yake huenda zimewekwa kufuta utambulisho wa Babilim programu-jalizi itakapofutwa. Leseni ya kulipia iliyounganishwa na tovuti kama hiyo haingeweza kurejeshwa kiotomatiki; ungelazimika kuwasiliana na Usaidizi wa Babilim kupitia %s. Ili kuhifadhi utambulisho, bofya Ghairi, ondoa tiki kwenye "Futa data yote ya Babilim wakati wa kusanidua" katika Mipangilio ya Babilim ya kila tovuti, kisha uzime tena. Zima hata hivyo?','This plugin\'s own version, so the service can tell you to update it if it\'s too old to talk to.'=>'Toleo la programu-jalizi hii yenyewe, ili huduma iweze kukuambia uisasishe ikiwa ni ya zamani mno kuweza kuwasiliana nayo.','This report does not name a valid plugin or theme and locale.'=>'Ripoti hii haitaji programu-jalizi au mandhari halali na lugha.','This report does not name an installed string.'=>'Ripoti hii haitaji mfuatano wa maandishi uliosakinishwa.','This report is missing a valid build to report against.'=>'Ripoti hii haina toleo halali la kuripotia.','This report will be posted publicly on GitHub and may be kept by third parties.'=>'Ripoti hii itachapishwa hadharani kwenye GitHub na inaweza kuhifadhiwa na wahusika wengine.','This restore code was not recognised for this site.'=>'Msimbo huu wa kurejesha haukutambuliwa kwa tovuti hii.','This site already has an active registration that can no longer be recovered automatically.'=>'Tovuti hii tayari ina usajili unaotumika ambao hauwezi tena kurejeshwa kiotomatiki.','This site has %1$d components across %2$d languages, which needs %3$d check batches; Babilim can handle at most %4$d per run. Reduce the managed languages in Settings or deactivate unused plugins and themes, then press Check again now.'=>'Tovuti hii ina vijenzi %1$d katika lugha %2$d, ambavyo vinahitaji makundi %3$d ya ukaguzi; Babilim inaweza kushughulikia upeo wa %4$d kwa kila uendeshaji. Punguza lugha zinazosimamiwa katika Mipangilio au zima programu-jalizi na mandhari zisizotumika, kisha bonyeza Angalia tena sasa.','This site has no purchase to show a code for.'=>'Tovuti hii haina ununuzi wa kuonyeshwa msimbo.','This site is already licensed. Reload the page.'=>'Tovuti hii tayari ina leseni. Pakia upya ukurasa.','This site is not registered with Babilim yet.'=>'Tovuti hii bado haijasajiliwa na Babilim.','This site is over the size the service accepts in one sync, so some items were left out: %1$d components and %2$d locales.'=>'Tovuti hii ni kubwa kuliko ukubwa unaokubaliwa na huduma katika usawazishaji mmoja, kwa hivyo baadhi ya vipengee viliachwa: vijenzi %1$d na lugha %2$d.','This site is part of a multisite network, which does not install new translations automatically. Translations that are already installed are still updated.'=>'Tovuti hii ni sehemu ya mtandao wa tovuti nyingi, ambao hausakinishi tafsiri mpya kiotomatiki. Tafsiri zilizosakinishwa tayari bado husasishwa.','This site is verified.'=>'Tovuti hii imethibitishwa.','This site must be verified first.'=>'Tovuti hii lazima ithibitishwe kwanza.','This site\'s URL, so the service can verify you own it.'=>'URL ya tovuti hii, ili huduma iweze kuthibitisha kuwa wewe ndiye mmiliki.','This site\'s address is too long for Babilim to register.'=>'Anwani ya tovuti hii ni ndefu mno kwa Babilim kuisajili.','This site\'s configured locale.'=>'Locale iliyosanidiwa ya tovuti hii.','This site\'s install public key, used to prove requests genuinely come from this site. Only the public half is ever sent.'=>'Ufunguo wa umma wa usakinishaji wa tovuti hii, unaotumika kuthibitisha kuwa maombi yanatoka kweli kwenye tovuti hii. Nusu ya umma pekee ndiyo hutumwa.','This site\'s locale code is not one Babilim can register.'=>'Msimbo wa lugha wa tovuti hii si ule ambao Babilim inaweza kusajili.','This string can\'t be reported from this site.'=>'Mfuatano huu hauwezi kuripotiwa kutoka tovuti hii.','This string is not among the translations installed on this site. Search again and pick it from the list.'=>'Mfuatano huu wa maandishi haumo miongoni mwa tafsiri zilizosakinishwa kwenye tovuti hii. Tafuta tena na uuchague kutoka kwenye orodha.','This translation was updated since you searched. Search again and pick the string from the new list.'=>'Tafsiri hii ilisasishwa tangu ulipotafuta. Tafuta tena na uchague mfuatano wa maandishi kutoka kwenye orodha mpya.','To translate this component, Babilim needs its source.'=>'Ili kutafsiri kijenzi hiki, Babilim inahitaji chanzo chake.','Too many attempts. Try again tomorrow.'=>'Majaribio mengi mno. Jaribu tena kesho.','Too many reports today. Try again tomorrow.'=>'Ripoti nyingi mno leo. Jaribu tena kesho.','Too many requests.'=>'Maombi mengi mno.','Toolbar'=>'Upau wa zana','Translating…'=>'Inatafsiri…','Translation does not load'=>'Tafsiri haipakiwi','Translation failed'=>'Tafsiri imeshindwa','Translation files you put in %s always take priority over Babilim\'s. They are kept unless you uncheck this.'=>'Faili za tafsiri unazoweka kwenye %s daima hupewa kipaumbele kuliko za Babilim. Huhifadhiwa isipokuwa ukiondoa tiki hapa.','Translation requested.'=>'Tafsiri imeombwa.','Translations'=>'Tafsiri','Type'=>'Aina','Type at least 2 characters to search.'=>'Andika angalau herufi 2 ili kutafuta.','Unexpected HTTP %d response.'=>'Jibu lisilotarajiwa la HTTP %d.','Uninstall'=>'Sanidua','Unknown kind: %s'=>'Aina isiyojulikana: %s','Unsafe domain: %s'=>'Kikoa si salama: %s','Unsafe locale: %s'=>'Locale isiyo salama: %s','Unsafe slug: %s'=>'Slug isiyo salama: %s','Unsafe text_domain: %s'=>'text_domain isiyo salama: %s','Up to 20 pending diagnostic events (e.g. a file that failed its integrity check), each just a code, component, and locale, and never any string content or translated text.'=>'Hadi matukio 20 ya uchunguzi yanayosubiri (k.m. faili iliyoshindwa ukaguzi wa uadilifu), kila moja ikiwa ni msimbo, kijenzi na lugha tu, bila maudhui yoyote ya maandishi au maandishi yaliyotafsiriwa.','Update'=>'Sasisha','Update available'=>'Sasisho linapatikana','Updates'=>'Masasisho','Updating…'=>'Inasasisha…','Upgrade this site'=>'Boresha tovuti hii','Upload and request'=>'Pakia na uombe','Upload cancelled.'=>'Upakiaji umeghairiwa.','Upload complete — translation requested.'=>'Upakiaji umekamilika — tafsiri imeombwa.','Upload expired before it finished'=>'Upakiaji ulikwisha muda kabla haujakamilika','Upload in progress — continue or cancel'=>'Upakiaji unaendelea — endelea au ghairi','Upload this component?'=>'Pakia kijenzi hiki?','Upload was not accepted'=>'Upakiaji haukukubaliwa','Uploading'=>'Inapakia','Uploading part %1$d of %2$d…'=>'Inapakia sehemu ya %1$d kati ya %2$d…','Uploading…'=>'Inapakia…','Verified'=>'Imethibitishwa','Verify response was missing site_token.'=>'Jibu la uthibitishaji halikuwa na site_token.','Version %s'=>'Toleo %s','What is sent when Babilim checks this site'=>'Kinachotumwa Babilim inapokagua tovuti hii','What is sent when you enable Babilim'=>'Kinachotumwa unapowasha Babilim','When something fails inside Babilim, send an error report to the Babilim service so it can be published as a public issue on GitHub. The report is sent as coming from this site, with the same authentication as every other request to the Babilim service. The service publishes only the error code and versions as a public issue on GitHub; the public issue contains no site address, content or file paths. Off by default.'=>'Kitu kikishindwa ndani ya Babilim, tuma ripoti ya hitilafu kwa Babilim service ili ichapishwe kama tatizo la umma kwenye GitHub. Ripoti hutumwa kana kwamba inatoka kwenye tovuti hii, kwa uthibitishaji uleule kama kila ombi lingine kwa Babilim service. Huduma huchapisha tu msimbo wa hitilafu na matoleo kama tatizo la umma kwenye GitHub; tatizo la umma halina anwani ya tovuti, maudhui wala njia za faili. Imezimwa kwa chaguo-msingi.','Where you saw this (optional)'=>'Ulipoona hili (si lazima)','While this is on, translations the service lists as available for the languages you manage are installed during the twice-daily sync.'=>'Hii ikiwa imewashwa, tafsiri ambazo huduma inaorodhesha kuwa zinapatikana kwa lugha unazozisimamia husakinishwa wakati wa usawazishaji mara mbili kwa siku.','WordPress.org'=>'WordPress.org','Wrong for this context'=>'Si sahihi kwa muktadha huu','Wrong meaning'=>'Maana si sahihi','Wrong plural form'=>'Umbo la wingi si sahihi','Wrong term'=>'Neno la istilahi si sahihi','Yes'=>'Ndiyo','You are not allowed to do this.'=>'Huruhusiwi kufanya hivi.','Your PHP version, for compatibility.'=>'Toleo lako la PHP, kwa ajili ya uoanifu.','Your WordPress version, to serve compatible translation files.'=>'Toleo lako la WordPress, ili kutoa faili za tafsiri zinazooana.','Your new restore code: %s. Keep it somewhere safe — the previous code no longer works.'=>'Msimbo wako mpya wa kurejesha: %s. Uhifadhi mahali salama — msimbo wa awali haufanyi kazi tena.','Your report is processed automatically by AI models and may improve this translation for other sites.'=>'Ripoti yako huchakatwa kiotomatiki na mifumo ya AI na inaweza kuboresha tafsiri hii kwa tovuti nyingine.','Your site answered, but not with what was expected. The REST API may be rewritten by another plugin, or that endpoint may be cached; please exclude /wp-json/babilim/v1/challenge from caching and rewriting.'=>'Tovuti yako ilijibu, lakini si kwa kilichotarajiwa. REST API huenda imebadilishwa na programu-jalizi nyingine, au sehemu hiyo ya mwisho huenda imehifadhiwa kwenye akiba; tafadhali ondoa /wp-json/babilim/v1/challenge kwenye uhifadhi wa akiba na ubadilishaji.','Your site took too long to answer. Please try again later, and check that your host is not too slow or overloaded.'=>'Tovuti yako ilichukua muda mrefu mno kujibu. Tafadhali jaribu tena baadaye, na uhakikishe mwenyeji wako si polepole sana au amelemewa.','Zip has no manifest.json.'=>'Zip haina manifest.json.','Zip is missing expected default file: %s'=>'Zip haina faili chaguomsingi inayotarajiwa: %s','Zip is missing expected file: %s'=>'Zip haina faili inayotarajiwa: %s','_manifest.json has an unexpected structure'=>'_manifest.json ina muundo usiotarajiwa','could not read _manifest.json: %s'=>'imeshindwa kusoma _manifest.json: %s','expected_manifest is missing or has an invalid \'%s\'.'=>'Sehemu ya \'%s\' haipo katika expected_manifest au ina thamani isiyo halali.','expected_manifest\'s \'server_build_id\' is not a valid build id.'=>'\'server_build_id\' ya expected_manifest si kitambulisho halali cha toleo (build id).','failed to parse _manifest.json: %s'=>'imeshindwa kuchanganua _manifest.json: %s','it would orphan %1$d of %2$d managed components (more than half)'=>'ingefanya %1$d kati ya vijenzi %2$d vinavyosimamiwa kuwa yatima (zaidi ya nusu)','it would orphan every managed %1$s component (%2$d of %2$d)'=>'ingefanya kila kijenzi cha %1$s kinachosimamiwa kuwa yatima (%2$d kati ya %2$d)','l10n.php entry count mismatch for %s'=>'Idadi ya maingizo ya l10n.php hailingani kwa %s','manifest.json has an invalid \'default_domain_entries\'.'=>'manifest.json ina default_domain_entries isiyo halali.','manifest.json has an invalid \'default_domain_files\'.'=>'manifest.json ina \'default_domain_files\' isiyo halali.','manifest.json in the zip is not valid JSON.'=>'manifest.json iliyo ndani ya zip si JSON halali.','manifest.json is missing or has an invalid \'%s\'.'=>'Sehemu ya \'%s\' haipo katika manifest.json au ina thamani isiyo halali.','manifest.json is missing or has an invalid \'build_no\'.'=>'Sehemu ya \'build_no\' haipo katika manifest.json au ina thamani isiyo halali.','manifest.json is missing or has an invalid \'entries\'.'=>'Sehemu ya \'entries\' haipo katika manifest.json au ina thamani isiyo halali.','manifest.json is missing or has an invalid \'extra_domains\'.'=>'Sehemu ya \'extra_domains\' haipo katika manifest.json au ina thamani isiyo halali.','manifest.json is missing or has an invalid \'files\'.'=>'Sehemu ya \'files\' haipo katika manifest.json au ina thamani isiyo halali.','manifest.json\'s \'%s\' does not match the expected value.'=>'\'%s\' ya manifest.json hailingani na thamani inayotarajiwa.','manifest.json\'s \'contract\' is not a valid version string.'=>'\'contract\' ya manifest.json si mfuatano halali wa toleo.','manifest.json\'s \'kind\' must be \'plugin\' or \'theme\'.'=>'\'kind\' ya manifest.json lazima iwe \'plugin\' au \'theme\'.','manifest.json\'s \'server_build_id\' is not a valid build id.'=>'\'server_build_id\' ya manifest.json si kitambulisho cha muundo halali.','manifest.json\'s \'status\' must be \'published\'.'=>'\'status\' ya manifest.json lazima iwe \'published\'.','nonce must be a hexadecimal string.'=>'nonce lazima iwe mfuatano wa heksadesimali.','per day'=>'kwa siku','rc_…'=>'rc_…','sha256 mismatch for %s'=>'kutolingana kwa sha256 kwa %s','sha256 mismatch for default/%s'=>'kutolingana kwa sha256 kwa default/%s','component kind in the sweep brake messageplugin'=>'programu-jalizi','component kind in the sweep brake messagetheme'=>'mandhari','problem report categoryOther'=>'Nyingine','translation statusAvailable'=>'Inapatikana','translation statusInstalled'=>'Imesakinishwa']];